if GetLocale() ~= "ruRU" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.era.warlock.dps.Name"] = "Все ветки"
L["rm.era.warlock.dps.Description"] = "Уровни 1–60, любая ветка талантов, в том числе в игровых мирах «Хардкор» и Self-Found; составлено по Wowhead, Icy Veins, Warcraft Tavern и симулятор. Молчит, пока вы применяете или поддерживаете заклинание, и в одиночной игре никогда не атакует противника, с которым сражается кто-то другой. Сначала Теневой транс от Сумерек; Ожог Тьмы и Жгучая боль для добивания цели в группе; одиночная цель, которая вот-вот умрёт, получает Похищение души (ради осколка или при Улучшенном похищении души), Ожог Тьмы или Поджигание, затем жезл, но никогда новые DoT. В движении — только мгновенные заклинания. Против трёх и более врагов: Адское Пламя, когда они рядом с вами, а у вас половина здоровья, иначе Огненный ливень. Одно проклятие: в рейдах Проклятие Тьмы или стихий, если его ни у кого нет, Проклятие рока в долгих боях с элитными противниками, иначе Проклятие агонии. Жертвенный огонь, когда он окупается («Разрушение», рейды или при 40% маны), Порча, Вытягивание жизни (в рейдах только при Уязвимости к Тьме). В одиночной игре: Темный союз, Жизнеотвод при хорошем здоровье, Похищение жизни, когда вы ранены, жезл. В остальных случаях Стрела Тьмы. Напоминания: Демонический доспех или Шкура демона, ваш питомец (демон Бездны в одиночной игре, бес в группе, суккуб для Демонического жертвоприношения), Господство Скверны, Демоническое жертвоприношение, Усиление проклятия, Жертвоприношение демона Бездны и Камень здоровья при низком здоровье, Канал здоровья. Распределение проклятий, Проклятие безрассудства на убегающего противника, Страх, Изгнание, камни души и создание камней здоровья остаются за вами."
L["rm.era.warlock.dps.icyveins.Name"] = "Проклятие и Порча в рейдах (Icy Veins)"
L["rm.era.warlock.dps.icyveins.Description"] = "Список Icy Veins для игровых миров с лимитом в 16 отрицательных эффектов — альтернатива рекомендуемой встроенной ротации чернокнижника, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. В рейдах только ваше проклятие и Порча, затем Стрела Тьмы, без Жертвенного огня и без Вытягивания жизни. Прокачка и подземелья — как в рекомендуемой встроенной ротации."
L["rm.era.warlock.dps.warcrafttavern.Name"] = "Дрейн-танк (Warcraft Tavern)"
L["rm.era.warlock.dps.warcrafttavern.Description"] = "Стиль прокачки Warcraft Tavern — альтернатива рекомендуемой встроенной ротации чернокнижника, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Бес, затем с 20 уровня суккуб. Жертвенный огонь, Вытягивание жизни и Порча, затем в одиночной игре Похищение жизни как заполнитель, как только вы изучите его четвёртый ранг (до этого — жезл), Жизнеотвод всякий раз, когда ваше здоровье почти полное, и Темный союз, пока мана питомца не полна. В рейдах все DoT, на которые хватает мест, затем Стрела Тьмы. Те же добивающие заклинания, проклятие и напоминания о безопасности, что и в рекомендуемой встроенной ротации; Страх на второго противника остаётся за вами."
L["rm.forever.warlock.dps.Name"] = "Все ветки"
L["rm.forever.warlock.dps.Description"] = "Все ветки талантов чернокнижника с 1 по 60 уровень, объединённые из Icy Veins, Wowhead и Method; шаги для ветки появляются, когда вы знаете её заклинания из талантов. Начинает бой Жертвенным огнем и Бичом агонии («Разрушение» заранее применяет Стрелу Тьмы), использует срабатывания Сумерек и Истребления, поддерживает Демоническое клеймо Жгучей болью. В движении применяет только мгновенные заклинания. Против групп врагов: Адское Пламя в группе, Огненный ливень, Порча и Бич агонии. Затем Бич судьбы на элитных противниках и боссах или Бич агонии, Проклятие стихий в группах и на элитных противниках, Жертвенный огонь, Порча, Вытягивание жизни, Поджигание и Ожог Тьмы; в одиночной игре заполняет Судорогами, Похищением жизни (с талантом на похищение) или жезлом; иначе Испепеление или Стрела Тьмы. Напоминания: доспех, демон (суккуб, иначе демон Бездны, иначе бес), Господство Скверны, Демоническое жертвоприношение с Демоническим союзом, Связка души, камни для оружия, Усиление проклятия и Бич сокрушения на втором враге. За вами остаются: отправка питомца в атаку, прочие проклятия, Страх, камни здоровья и другие цели. В Forever здоровье и мана скрыты от аддонов, поэтому окно добивания (Похищение души, Ожог Тьмы как завершающий удар), Жизнеотвод, Канал здоровья и похищение жизни при ранении выбираете вы."
L["rm.forever.warlock.dps.icyveins.Name"] = "Все ветки (Icy Veins)"
L["rm.forever.warlock.dps.icyveins.Description"] = "Прокачка чернокнижника по Icy Veins: в одиночной игре основное заполняющее действие — жезл, демон по умолчанию — демон Бездны, «Колдовство» и «Разрушение» приносят своего демона в жертву и играют без него (с 41 и 55 уровня), «Демонология» поддерживает Демоническое клеймо и использует Жертвенный огонь только как заполнитель, а «Разрушение» вешает Бич сокрушения на самого живучего врага в группе и применяет Поджигание по готовности, как только изучено Испепеление. Выбирайте её вместо рекомендуемой встроенной ротации чернокнижника, если следуете Icy Veins. В Forever здоровье, мана и время до смерти цели скрыты от аддонов, поэтому Похищение жизни при ранении, Жизнеотвод и выбор целей, которые проживут достаточно долго для DoT, остаются за вами. Альтернатива рекомендуемой встроенной ротации чернокнижника «Урон», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.forever.warlock.dps.wowhead.Name"] = "Все ветки (Wowhead)"
L["rm.forever.warlock.dps.wowhead.Description"] = "Чернокнижник 30 уровня по Wowhead: «Колдовство» и «Демонология» танкуют похищением с суккубом (Порча и Бич агонии, без Жертвенного огня, затем Похищение жизни до конца боя; в Forever здоровье и мана скрыты, поэтому Жизнеотвод — на ваше усмотрение), «Демонология» поддерживает Демоническое клеймо и накладывает Бич агонии только на крупные цели, «Разрушение» вешает Бич агонии, Порчу и Жертвенный огонь на каждого противника, применяет Поджигание незадолго до окончания Жертвенного огня, приберегает Ожог Тьмы для добивания и стреляет из жезла с демоном Бездны. Усиление проклятия при каждой готовности; Проклятие стихий и Бич судьбы — только на элитных противниках и боссах; раздела для групп врагов нет. Руководства Wowhead заканчиваются на 30 уровне. Альтернатива рекомендуемой встроенной ротации чернокнижника «Урон», отключена по умолчанию: включите её и выключите ту или повысьте её приоритет."
L["rm.mop.warlock.affliction.Name"] = "Рекомендуемая"
L["rm.mop.warlock.affliction.Description"] = "Рекомендуется для «Колдовства» с 10 по 90 уровень (выбирается при специализации «Колдовство»). Заранее применяет Блуждающий дух или Нестабильное колдовство, начинает бой со свежим элитным противником Горящей душой и Обменом душ, поддерживает Агонию, Порчу и Нестабильное колдовство (досрочно обновляя их, пока действует Черная душа: Страдание), применяет Блуждающий дух всякий раз, когда он заканчивается, а у вас два осколка (или во время Черной души), поддерживает Похищение души ради осколка, когда Блуждающий дух заканчивается, а осколков нет, Похищение души ниже 20%, иначе Гибельная хватка (до 42 уровня — Стрела Тьмы). Семя порчи против трёх и более врагов (с Горящей душой — против шести). В движении: мгновенные заклинания и Пламя Скверны. Напоминания: ваш питомец, Узы Тьмы, Проклятие стихий в группе, Черная душа, страж ужаса или инфернал, Гримуар служения или жертвоприношения, Жизнеотвод, защитные способности. За вами остаются: распространение DoT на другие цели и перенос их Обменом душ между целями."
L["rm.mop.warlock.affliction.warcrafttavern.Name"] = "Накопление для Блуждающего духа (Warcraft Tavern)"
L["rm.mop.warlock.affliction.warcrafttavern.Description"] = "По умолчанию выключена. Политика осколков Warcraft Tavern и Method: то же поддержание DoT, что и в рекомендуемой встроенной ротации «Колдовство», но Блуждающий дух приберегается до четырёх осколков или Черной души: Страдание, а ниже 20% Горящая душа и Обмен душ обновляют все DoT всякий раз, когда у вас есть осколок. Чтобы использовать её, включите её и выключите рекомендуемую встроенную ротацию «Колдовство»."
L["rm.mop.warlock.demonology.Name"] = "Рекомендуемая"
L["rm.mop.warlock.demonology.Description"] = "Рекомендуется для «Демонологии» с 10 по 90 уровень (выбирается при специализации «Демонология»). В облике заклинателя: Порча, Рука Гул'дана по зарядам, вторая Рука Гул'дана перед Метаморфозой, когда Пламя Тьмы с одним наложением вот-вот спадёт, Метаморфоза вместе с Черной душой: Знание (или почти при полной демонической ярости), Ожог души при двух наложениях Огненных Недр или ниже 25%, Адское пламя против четырёх и более врагов, Стрела Тьмы. В Метаморфозе: Рок, Касание Хаоса для поддержания Порчи, Ожог души при Огненных Недрах, Жар преисподней или Луч Бездны против групп, Касание Хаоса и подсказка выйти из неё, когда Черная душа не действует, а демонической ярости 300 или меньше. Напоминания: страж Скверны (или страж гнева), Узы Тьмы, Черная душа, Стая бесов, Гримуар: страж Скверны, страж ужаса или инфернал, Жизнеотвод, Канал здоровья в одиночной игре. За вами остаются: Буря Скверны (автоприменение питомца) и Демонический прыжок."
L["rm.mop.warlock.demonology.guide.Name"] = "Накопление Огненных Недр (руководства)"
L["rm.mop.warlock.demonology.guide.Description"] = "По умолчанию выключена. Общее мнение руководств (Method, wowtbc.gg, Warcraft Tavern, Wowhead): рекомендуемая встроенная ротация «Демонология», за исключением того, что в облике заклинателя Метаморфоза ждёт 900 ед. демонической ярости или Черной души, а Ожог души применяется только при восьми наложениях Огненных Недр или ниже 25%, чтобы наложения тратились в облике демона. Чтобы использовать её, включите её и выключите рекомендуемую встроенную ротацию «Демонология»."
L["rm.mop.warlock.destruction.Name"] = "Рекомендуемая"
L["rm.mop.warlock.destruction.Description"] = "Для «Разрушения» с 10 по 90 уровень (выбирается при специализации «Разрушение»). Заранее применяет Испепеление, поддерживает Жертвенный огонь, никогда не держит два заряда Поджигания, тратит угли на Стрелу Хаоса (ниже 20% — Ожог Тьмы) при 3,5 ед. углей или во время Черной души: Изменчивость, использует Обратный поток на Испепеление и заполняет Испепелением; умирающая цель получает Ожог Тьмы. Против трёх и более врагов: Огненный ливень и Огонь и сера против четырёх, затем Жертвенный огонь, Поджигание и Испепеление и подсказка выключить Огонь и серу, когда угли кончатся. В движении: Ожог Тьмы, Поджигание, Пламя Скверны. Напоминания: ваш питомец или Гримуар жертвоприношения, Пламя Зорота, Узы Тьмы, Черная душа, Хаос против двух и более врагов (на вторую цель применяете его сами), страж ужаса или инфернал, Углеотвод и защитные способности."
L["rm.mop.warlock.unspecialized.Name"] = "Без специализации"
L["rm.mop.warlock.unspecialized.Description"] = "Для чернокнижника без специализации (уровни 1–9 или позже, пока вы её не выбрали). Порча для начала боя и её поддержание, Похищение жизни при здоровье ниже половины, Стрела Тьмы. Напоминания: демон Бездны в одиночной игре (бес в группе) и Камень здоровья между боями."
L["rm.retail.warlock.affliction.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warlock.affliction.Description"] = "Рекомендуется для специализации «Колдовство» в Midnight. В бою игра теперь скрывает от аддонов ваши DoT, срабатывания, время восстановления и здоровье, поэтому эта ротация показывает собственное предложение Боевого помощника Blizzard (ротация одной кнопкой, которая поддерживает Агонию и Порчу, тратит осколки души на Нестабильное колдовство и берёт на себя Гримуар жертвоприношения) и приостанавливается, пока вы применяете или поддерживаете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Призыв созерцателя тьмы в бою, Призыв охотника Скверны между боями, если вы не принесли демона в жертву, Управление демоном против прерываемого заклинания (оно загорается только там, где игра позволяет прочитать заклинание), Темный пакт и Твердая решимость по готовности в бою (здоровье на Retail скрыто, поэтому момент их применения — на ваше усмотрение)."
L["rm.retail.warlock.affliction.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.warlock.affliction.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft (Пожинатель душ) читает таймеры DoT, Сумерки и Нестабильный осколок, которые Midnight скрывает в бою. Блуждающий дух перед боем; Семя порчи против трёх и более врагов, вступивших в бой без вашей Порчи; Блуждающий дух; Агония и Порча или Усыхание, если осталось меньше 3 секунд; Темная жатва при двух осколках души или меньше; Нестабильное колдовство при 5 осколках; Гибельная хватка, иначе Стрела Тьмы, при двух зарядах Сумерек; Нестабильное колдовство при Нестабильном осколке или при 4 осколках; Похищение души; Стрела Тьмы. Напоминания: Призыв созерцателя тьмы, когда Темная жатва восстанавливается, Зловредность, ваш охотник Скверны и общие напоминания."
L["rm.retail.warlock.demonology.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warlock.demonology.Description"] = "Рекомендуется для специализации «Демонология» в Midnight. Показывает предложение Боевого помощника Blizzard (Призыв зловещих охотников, Рука Гул'дана, Демонический заряд, Вытягивание сил и Призыв демонического тирана) и приостанавливается, пока вы применяете или поддерживаете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Призыв демонического тирана, пока зловещие охотники, призванные за последние 12 секунд, ещё здесь, Гримуар: властелин бесов, Гримуар: разоритель Скверны и Призыв стража ужаса в бою, Призыв стража Скверны между боями, Управление демоном, Темный пакт, Твердая решимость."
L["rm.retail.warlock.demonology.icyveins.Name"] = "Для справки (Icy Veins)"
L["rm.retail.warlock.demonology.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Icy Veins и SimulationCraft (Демонопоклонник) читает Сердце демона, число бесов и таймеры восстановления, которые Midnight скрывает в бою. Вытягивание сил, Демонический заряд и Стрела Тьмы перед боем; затем Вытягивание сил при одном Сердце демона или без него, Гримуар: властелин бесов, Гримуар: разоритель Скверны, Призыв стража ужаса, Призыв зловещих охотников, Призыв демонического тирана при 5 осколках души, Имплозия против трёх и более врагов, вступивших в бой, Гибель миров, Рука Гул'дана при 3 осколках и более, Адская стрела при менее чем 3, Демонический заряд при Сердце демона и менее чем 4 осколках, Стрела Тьмы."
L["rm.retail.warlock.destruction.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warlock.destruction.Description"] = "Рекомендуется для специализации «Разрушение» в Midnight. Показывает предложение Боевого помощника Blizzard (Жертвенный огонь или Усыхание, Поджигание, Стрела Хаоса, Огненный ливень, Ожог души, Зловредность) и приостанавливается, пока вы применяете или поддерживаете заклинание или у вас нет враждебной цели. Напоминания о том, что оно упускает: Призыв инфернала в бою, Призыв беса между боями, если вы не принесли демона в жертву, Управление демоном, Темный пакт, Твердая решимость. Хаос на второй цели остаётся за вами."
L["rm.retail.warlock.destruction.icyveins.Name"] = "Стрела Хаоса до переполнения, для справки (Icy Veins)"
L["rm.retail.warlock.destruction.icyveins.Description"] = "Только для справки, по умолчанию выключена: порядок Призывателя огня по Icy Veins, который тратит осколки души на Стрелу Хаоса до их переполнения и применяет Ожог Тьмы и Направленный демонический огонь по готовности. Огненный ливень против трёх и более врагов, вступивших в бой; поддержание Усыхания или Жертвенного огня; Призыв инфернала; Зловредность; Ожог Тьмы; Ожог души при менее чем 4 осколках; Стрела Хаоса при 4 и более; Катаклизм; Адская стрела при менее чем 4; Направленный демонический огонь; Поджигание; Испепеление."
L["rm.retail.warlock.destruction.simc.Name"] = "Для справки (SimulationCraft)"
L["rm.retail.warlock.destruction.simc.Description"] = "Только для справки, по умолчанию выключена: порядок SimulationCraft читает Жертвенный огонь, Обратный поток, заряды и таймеры восстановления, которые Midnight скрывает в бою. Ожог души и Испепеление перед боем; против трёх и более врагов, вступивших в бой — Огненный ливень при 3 осколках души и Катаклизм; затем Ожог души при 4 осколках или меньше, Стрела Хаоса только при 5, Поджигание при двух зарядах или при менее чем 4 осколках без Обратного потока, Призыв инфернала, Зловредность, Усыхание или Жертвенный огонь в последние 30% длительности, Гибель миров, Катаклизм, Адская стрела при 3 осколках или меньше, Испепеление."
L["rm.retail.warlock.initial.Name"] = "Боевой помощник Blizzard"
L["rm.retail.warlock.initial.Description"] = "Рекомендуется до выбора специализации (пока игра сообщает начальную специализацию чернокнижника). Подсвечивает заклинание, которое Боевой помощник Blizzard предлагает следующим, — единственный совет по ротации, который игра ещё позволяет аддону читать в бою в Midnight; пока вы применяете или поддерживаете заклинание, ротация ждёт. Рядом с ним — общие напоминания всех встроенных ротаций чернокнижника, каждое — как только вы знаете соответствующее заклинание. Когда на 10 уровне вы выбираете специализацию, её встроенные ротации вступают в силу."
L["rm.sod.warlock.fire.Name"] = "Огонь (SoD)"
L["rm.sod.warlock.fire.Description"] = "«Разрушение» для сезона открытий; выбирается, как только выгравирована Стрела Хаоса или Испепеление; составлено по симулятор (6-я фаза) и Wowhead. Ожог Тьмы и Жгучая боль для добивания; мгновенные заклинания в движении; положительный эффект Испепеления, Огненное озеро и Адское Пламя против групп; проклятие (Проклятие безрассудства в группе, если его ни у кого нет, Проклятие рока в долгих боях с элитными противниками, иначе Проклятие агонии); Поджигание — только для поддержания Обратного потока; Жертвенный огонь и положительный эффект Испепеления постоянно поддерживаются; ниже 35% — Ожог души под Истреблением вместо Стрелы Хаоса; срабатывания «Ожог души!»; Стрела Хаоса; в одиночной игре Похищение жизни с Мастером-чаротворцем и Жизнеотвод; Испепеление (Стрела Тьмы, пока вы его не выгравировали). Напоминания: Доспех Скверны, бес, Усиление проклятия и напоминания о безопасности."
L["rm.sod.warlock.fire.icyveins.Name"] = "Огонь, Поджигание по готовности (SoD, Icy Veins)"
L["rm.sod.warlock.fire.icyveins.Description"] = "«Разрушение» для сезона открытий по Icy Veins и Warcraft Tavern — альтернатива рекомендуемой встроенной ротации «Огонь» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Жертвенный огонь постоянно поддерживается, Поджигание и Стрела Хаоса по готовности (Стрела Хаоса и ниже 35%), положительный эффект Испепеления, Ожог души под Истреблением ниже 35%, Испепеление как заполнитель; проклятие урона — только в движении, а в группе — Проклятие безрассудства, если его ни у кого нет."
L["rm.sod.warlock.shadow.Name"] = "Тьма, Колдовство и страж Скверны (SoD)"
L["rm.sod.warlock.shadow.Description"] = "Билды «Колдовства» и со стражем Скверны для сезона открытий, а также любой чернокнижник сезона открытий, которому не подходит другая встроенная ротация; составлено по симулятор (6-я фаза), Wowhead и Icy Veins. Срабатывания Сумерек; Ожог Тьмы или Похищение души для добивания цели в группе; умирающая одиночная цель получает Похищение души, а не DoT; мгновенные заклинания в движении; Огненное озеро и Адское Пламя против групп; проклятие (Проклятие безрассудства в группе, если его ни у кого нет, иначе Проклятие агонии); Нестабильное колдовство, Похищение жизни с Мастером-чаротворцем, Пламя Тьмы (до него — Жертвенный огонь), Порча, Блуждающий дух, Вытягивание жизни (каждое обновляется менее чем за 6 секунд, если выгравировано Призывание); Похищение души ниже 20%, если выгравирован Вытягивание души; поддержание здоровья и маны в одиночной игре и жезл; Стрела Тьмы. Напоминания: Доспех Скверны, ваш питомец (страж Скверны, как только выгравирован), Жизнеотвод для питомца, у которого мало маны, Усиление проклятия и напоминания о безопасности. Распределение проклятий и Залп стрел Тьмы против групп остаются за вами."
L["rm.sod.warlock.shadow.simulator.Name"] = "Тьма, Похищение души как заполнитель (SoD, симулятор)"
L["rm.sod.warlock.shadow.simulator.Description"] = "Список «Колдовства» 6-й фазы по симулятор для билда с Вытягиванием души — альтернатива рекомендуемой встроенной ротации «Тьма» для сезона открытий, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. Похищение души — заполнитель при любом здоровье цели, а следующий шаг показывается, как только он нужен, чтобы вы могли ради него прервать поддержание; любое другое поддержание доводится до конца. Нестабильное колдовство и Пламя Тьмы обновляются, когда остаётся 7,5 секунды, Проклятие агонии и Порча — когда остаётся 6, Похищение жизни с Мастером-чаротворцем, Блуждающий дух, Стрела Тьмы только при срабатывании Теневого транса, Вытягивание жизни, Жизнеотвод при мане ниже 10%. Те же напоминания, что и в рекомендуемой встроенной ротации."
L["rm.sod.warlock.tank.Name"] = "Танк (SoD, Метаморфоза)"
L["rm.sod.warlock.tank.Description"] = "Танк для сезона открытий; выбирается, как только выгравирована Метаморфоза; составлено по симулятор, Icy Veins, Wowhead и Warcraft Tavern. Теневой рассекающий удар всякий раз, когда Решимости защитника нет или она заканчивается, срабатывание «Ожог души!», Испепеление для поддержания его огненного положительного эффекта; против трёх и более врагов — Теневой рассекающий удар, Огненное озеро, Пламя Тьмы и Адское Пламя. Затем проклятие (Проклятие агонии, иначе Проклятие безрассудства, если его ни у кого нет), Пламя Тьмы (Жертвенный огонь, пока вы его не выгравировали), Похищение жизни с Мастером-чаротворцем, Порча, Вытягивание жизни, Поджигание ради Обратного потока, Ожог души под Истреблением ниже 35% и Жгучая боль как заполнитель для угрозы. Напоминания: Метаморфоза, Доспех Скверны, ваш питомец, Обжигающий жар, Демоническая грация, Отмщение при низком здоровье, Устрашение, когда цель атакует кого-то другого, Демонический вой против групп, Усиление проклятия, Жизнеотвод для питомца, у которого мало маны. Инфернальная броня остаётся за вами."
L["rm.tbc.warlock.dps.icyveins.Name"] = "Все ветки (Icy Veins)"
L["rm.tbc.warlock.dps.icyveins.Description"] = "Все ветки талантов с 1 по 70 уровень. Проклятие, затем Нестабильное колдовство, Жертвенный огонь, Порча и Вытягивание жизни по мере изучения, Стрела Тьмы или Испепеление; сначала срабатывания Сумерек и Отдачи; Семя порчи, Адское пламя и Неистовство Тьмы при трёх и более врагах. В одиночной игре похищает жизнь, когда вы ранены, использует Жизнеотвод, жезл, а на умирающей цели — Похищение души или добивающее заклинание. Напоминания: Доспех Скверны, Демонический доспех или Шкура демона, ваш демон, жертвоприношение, Связка души, Усиление проклятия и Раскол души. Страх и прочие проклятия остаются за вами."
L["rm.tbc.warlock.dps.wowhead.Name"] = "Дрейн-танк (Wowhead)"
L["rm.tbc.warlock.dps.wowhead.Description"] = "Чернокнижник по руководствам Wowhead — альтернатива рекомендуемой встроенной ротации «Чернокнижник» от Icy Veins, отключена по умолчанию: включите её и выключите ту или повысьте её приоритет. В одиночной игре танкует похищением (дрейн-танк): Похищение жизни становится основным заклинанием, как только ваши DoT наложены, а Жертвенный огонь и Вытягивание жизни приберегаются для элитных противников. В группе Жертвенный огонь накладывается всегда, после Порчи и Вытягивания жизни. В остальном — как рекомендуемая встроенная ротация."
